/* FANUC SPOT alarm codes — generated by tools/fetch-alarms.js,
 * DO NOT EDIT; re-run the tool instead. 227 codes, 2026-10-22.
 * Source: http://linuxsand.info/fanuc/ — internal reference copy, by permission. */
(function (global) {
  var data = {
    "000": "SPOT-000 Unknown error (SWG0)\nCause:  An internal error has occurred.\nRemedy:  Cold start the controller.",
    "001": "SPOT-001 Backup not closed %s\nCause:  The backup state spot welding instruction BU=* was used before a weld, but the backup state was in the open (BU=O)\nposition at the time the instruction was executed. Note: BU=* indicates that the backup state remains unchanged from\nthe last position. To use this command before a weld, the previous backup state must be BU=C (closed position).\nRemedy:  Make sure that the backup state is closed when using the BU=* command. Either change BU=* to BU=C, or insert a\nBACKUP=CLOSE statement before this statement.",
    "002": "SPOT-002 Iso contactor fault %s\nCause:  The isolation contactor on the specified weld controller is in a fault condition. If no progr am is running, then this\nmessage is posted if either the Iso contactor output is high or the Iso contactor input is high. If a program is running or\na manual weld is being executed then the output, if defined, must be high and the input, if defined, must be high too.\nRemedy:  Verify the contactor state. Make sure that the correct contactor instruction has been programmed in the teach pendant\nprogram. Verify the input status and configuration in the Weld Interface I/O screen. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Weld Interface.",
    "003": "SPOT-003 Water saver OK fault %s\nCause:  The water saver input is low.\nRemedy:  Verify the water flow and water saver operation. Verify the input configuration and status from the Spot Equip I/O\nscreen. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "004": "SPOT-004 Water flow OK fault %s\nCause:  The water flow OK input is low.\nRemedy:  Verify the water flow and sensor operation. Verify the input configuration and status from the Spot Equip I/O screen.\nUsing the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "005": "SPOT-005 X-former OK fault %s\nCause:  The transformer OK input is low.\nRemedy:  Verify the weld transformer status. Verify the input configuration and status from the Spot Equip screen. Using the\nteach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "006": "SPOT-006 Weld enable mismatch %s\nCause:  The weld enable status from the weld controller does not match the weld enable status on the robot.\nRemedy:  Check the Weld Enable status from the Soft Panel menu and compare it with the weld cont roller Weld Enable status.\nThese must be the same. The Soft Panel can be accessed using the teach pendant.\n1. Press MENU.\n2.  Select Soft Panel.\n3.  Press F2, Applic.\nVerify I/O configuration and status from the Spot Equip I/O screen. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].",
    "007": "SPOT-007 Weld in process timeout %s\nCause:  The robot timed out waiting for the Weld in Process input from the weld controller.\nRemedy:  Check the weld controller for reason for the alarm. Check the Weld I/O menu, as well as the equipment I/O wiring.\nUsing the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Weld Interface.\nIf the input is going high, try increasing the timeout by increasing the Weld in process time-out signal setting. This\nsignal can be set from the Spot Config menu at Controlled start. The default value is 2000 ms, or 2 seconds.",
    "008": "SPOT-008 Weld complete timeout %s\nCause:  The robot timed out waiting for the Weld Complete input from the weld controller.\nRemedy:  Check the weld controller for the reason for the alarm. Check the Weld I/O menu, as well as the equipment I/O wiring.\nUsing the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Weld Interface.\nIf the input is going high, try increasing the timeout by increasing the Weld complete time-out signal setting. This\nsignal can be set from the Spot Config menu at controlled start. The default value is 2000 ms, or 2 seconds.",
    "009": "SPOT-009 Got weld complete early %s\nCause:  The Weld Complete input was detected before the Weld in Process input was received.\nRemedy:  Check the length of the weld controllers Weld complete output. Verify the input configuration in the Weld Interface\nI/O screen. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Weld Interface.",
    "010": "SPOT-010 Major alarm detected %s\nCause:  A Major Alarm was received.\nRemedy:  Check the weld controller for the reason for the alarm. Verify the input configuration and status in the Weld Interface\nI/O screen. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Weld Interface.\nVerify that the correct configuration is being used within the Spot Config menu. This menu can be accessed at\ncontrolled start.",
    "011": "SPOT-011 Minor alarm detected %s\nCause:  A Minor Alarm was received.\nRemedy:  Check the weld controller for reason of alarm. Verify the input configuration and status in the Weld Interface I/O\nscreen. Using the teach pendant:\n1. Press I/O.\n2. Press F1,[TYPE].\n3.  Select Weld Interface.\nVerify that the correct configuration is being used within the Spot Config menu. This menu can be accessed at\nControlled start.",
    "012": "SPOT-012 Bad schedule (S=*) %s\nCause:  An invalid weld schedule was programmed in the teach pendant program.\nRemedy:  Check the S= value of the current line of the teach pendant program. The smallest schedule number allowed is 0. For\ndigital weld controllers, the largest schedule number allowed depends on the width of the Weld Schedule group output.\nIf this GOUT is 4 I/O points wide, then the maximum schedule is 15. If the GOUT is 5 I/O points wide, then the\nmaximum schedule is 31. For serial weld controllers, the maximum schedule is 32. Re-program the S= value in the\nteach pendant program.",
    "013": "SPOT-013 Undefined pressure (P=*)\nCause:  The valve pressure spot welding instruction P=* was encountered in a teach pendant program, but no previous pressure\nvalue had been assigned. Note: P=* indicates that the valve pressure remains unchanged from the last value.\nRemedy:  Be sure to include a direct pressure value instead of using *.",
    "014": "SPOT-014 BACKUP CLOSE DETECT timed out %s\nCause:  The robot timed out waiting for the backup close detect input. This input indicates that the gun has reached the backup\nclose position.\nRemedy:  Check the gun operation and sensor states. Check the Equipment I/O menu and verify signal status, as well as the\nequipment I/O wiring. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.\nIf the input is going high, try increasing the timeout by increasing the Backup close detect signal setting. This signal\ncan be set from the Spot Config menu at Controlled start. The default value is 2000 ms, or 2 seconds.",
    "015": "SPOT-015 GUN CLOSE DETECT timed out %s\nCause:  The robot timed out waiting for the gun close detect input. This input indicates that the gun has closed.\nRemedy:  Check the gun operation and sensor states. Check the Equipment I/O menu, as well as the equipment I/O wiring. Using\nthe teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.\nIf the input is going high, try increasing the timeout by increasing the Gun close detect signal setting. This signal can\nbe set from the Spot Config menu at Controlled start. The default value is 2000 ms, or 2 seconds.",
    "016": "SPOT-016 BACKUP OPEN DETECT timed out %s\nCause:  The robot timed out waiting for the Backup Open Detect input. This input indicates that the gun has reached the\nbackup open position.\nRemedy:  Check the gun operation and sensor states. Check the Equipment I/O menu, as well as the equipment I/O wiring. Using\nthe teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.\nIf the input is going high, try increasing the timeout by increasing the Backup open detect signal setting. This signal\ncan be set from the Spot Config menu at Controlled start. The default value is 2000 ms, or 2 seconds.",
    "017": "SPOT-017 GUN OPEN DETECT timed out %s\nCause:  The robot timed out waiting for the gun open detect input. This input indicates that the gun has opened.\nRemedy:  Check the gun operation and sensor states. Check the Equipment I/O menu, as well as the equipment I/O wiring. Using\nthe teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.\nIf the input is going high, try increasing the timeout by increasing the Gun open detect signal setting. This signal can\nbe set from the Spot Config menu at Controlled start. The default value is 2000 ms, or 2 seconds.",
    "018": "SPOT-018 Serial comm error %s\nCause:  A serial communications error was detected.\nRemedy:  Ensure that all cables to the serial port are properly connected, and that the weld controller is powered on. The error\ncode that is appended to this error message is the status of attempted read/write operation.",
    "019": "SPOT-019 Serial polling timeout\nCause:  A timeout occurred while polling the serial weld controller for status information.\nRemedy:  Ensure that all cables to the serial port are properly connected, and that the weld controller is powered on. Retry the\ncommand.",
    "020": "SPOT-020 Not in safe starting position\nCause:  The robot has been jogged away from the position where the teach pendant was enabled.\nRemedy:  Move the robot back to the position where the teach pendant was enabled, abort the program, or continue (in linear\nmotion) from position where the robot is currently positioned.",
    "021": "SPOT-021 GUN CLOSE DETECT input is on %s\nCause:  The Gun Close Detect input is high at the same time that the Gun open detect input is to be checked.\nRemedy:  Check the gun operation and sensor states. Verify the input status and configuration from the Spot Equip I/O screen.\nUsing the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "022": "SPOT-022 GUN OPEN DETECT input is on %s\nCause:  The Gun Open Detect input is high at the same time that the Gun Close Detect input is to be checked.\nRemedy:  Check the gun operation and sensor states. Verify the input status and configuration from the Spot Equip I/O screen.\nUsing the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "023": "SPOT-023 BU CLOSE DETECT is on %s\nCause:  The Gun Open Detect input is high at the same time that the Gun Close Detect input is to be checked.\nRemedy:  Check the gun operation and sensor states. Verify the input status and configuration from the Spot Equip I/O screen.\nUsing the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "024": "SPOT-024 BU OPEN DETECT is on %s\nCause:  The Gun Open Detect input is high at the same time that the Gun Close Detect input is to be checked.\nRemedy:  Check the gun operation and sensor states. Verify the input status and configuration from the Spot Equip I/O screen.\nUsing the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "025": "SPOT-025 Bad pressure (P=*) %s\nCause:  An invalid binary valve pressure was programmed in the teach pendant program.\nRemedy:  In the teach pendant program, check the valve pressure spot welding instruction P= value. Note: The smallest valve\npressure allowed is 0. For digital weld controllers, the largest pressure number allowed depends on the width of the\nValve Pressure group output. If this GOUT is 4 I/O points wide, then the maximum pressure is 15. If the GOUT is 5\nI/O points wide, then the maximum pressure is 31. For serial weld controllers, the maximum pressure is 15.\nRe-program the P= value in the teach pendant program.",
    "026": "SPOT-026 Reset welder timeout %s\nCause:  The robot timed out waiting for the weld controller to reset a major fault.\nRemedy:  Check the weld controller for reason of alarm. Verify the input status and configuration in the Weld Interface I/O\nscreen. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Weld Interface.\nVerify the setup within the Spot Config menu. This menu can be accessed at Controlled start.",
    "027": "SPOT-027 Serial sequence not started\nCause:  A system failure has caused internal synchronization problems. Serial interface task with welder did not correctly\ninitiate.\nRemedy:  Cold start the controller.",
    "028": "SPOT-028 Serial initialization failed\nCause:  Serial port specification is invalid.\nRemedy:  Make sure that the port exists.",
    "029": "SPOT-029 Serial option not loaded\nCause:  Incorrect options loaded for serial weld control.\nRemedy:  Make sure serial options properly loaded.",
    "030": "SPOT-030 Gun contactor fault %s\nCause:  The specified gun contactor is in a fault condition. If a program is running, or a manual weld is being executed, then\nthe output, if defined, must be high, and the input, if defined, must be high too.\nRemedy:  Verify the contactor state. Make sure that the correct contactor instruction has been programmed in the teach pendant\nprogram. Verify the input status and configuration in the Spot Equip I/O screen. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.\nVerify the setup within the Spot Config menu. This menu can be accessed at Controlled start.",
    "031": "SPOT-031 Gun open fault %s\nCause:  This error is only posted for set/reset type guns. The shot pin was not set correctly, so the gun could not be opened.\nRemedy:  Check the setting of the shot pin. Make sure the shot pin has been made before attempting to close the gun. Check the\nEquipment I/O and verify that the input is assigned correctly. Verify that the input is being made when the gun is\nopened. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "032": "SPOT-032 Gun close fault %s\nCause:  The Gun Close Detect input was not received within the specified timeout period.\nRemedy:  Check the gun operation and sensor states. Check the Equipment I/O and verify that the input is assigned correctly.\nVerify that the input is being made when the gun is closed. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "033": "SPOT-033 Backup open fault %s\nCause:  The BU (backup) open detect input was not received within the specified timeout period.\nRemedy:  Check the gun operation and sensor states. Check the Equipment I/O and verify that the input is assigned correctly.\nVerify the input is being made when the gun is opened. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "034": "SPOT-034 Backup close fault %s\nCause:  The BU (backup) close detect input was not received within the specified timeout period.\nRemedy:  Check the gun operation and sensor states. Check the Equipment I/O and verify that the input is assigned correctly.\nVerify the input is being made when the gun is closed. Using the teach pendant.\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "035": "SPOT-035 Invalid equipment (%s defined)\nCause:  An invalid equipment number was specified.\nRemedy:  The current number of equipment for which the system is configured is displayed in the error message. Only use the\nvalue one up to and including the number posted on the error line. If you need to increase the number of equipment,\nthen perform a Controlled start, and type the new number of equipment in the Spot Config menu.",
    "036": "SPOT-036 Invalid weld controller (%s defined)\nCause:  An invalid weld controller number was specified.\nRemedy:  The current number of weld controllers that the system is configured for is displayed in the error message. Only use\nthe value one up to and including the number posted on the error line. If you need to increase the number of weld\ncontrollers, then perform a controlled start, and define the new number of weld controllers when prompted during the\nSETUP APPLICATION menu.",
    "037": "SPOT-037 No gun contactors defined\nCause:  The Gun contactor teach pendant instruction was programmed, but no gun contactors are defined.\nRemedy:  Gun contactors are defined at Controlled start, from the Spot Config menu. If extra gun contactors are defined at\nControlled start, then the Equipment I/O menu will allow you to define the I/O for the gun contactor. To perform a\nControlled start:\n1.  Turn the controller off.\n2.  On the teach pendant, press and hold the PREV and NEXT keys. While you hold these keys, press the ON/OFF\nbutton on the controller.\n3.  Select controlled start, and press ENTER.",
    "038": "SPOT-038 Stud feeders low\nCause:  The stud low detect prox switch in the feed hopper for the current Power unit has indicated that the hopper needs more\nstuds.\nRemedy:  Refill the hopper, or, if it is not low, check the function of the prox.",
    "039": "SPOT-039 System air pressure below 85psi\nCause:  The welder power unit air pressure detect switch has indicated that the system air has fallen below the minimum\noperating level of 85 psi.\nRemedy:  Increase system air pressure.",
    "040": "SPOT-040 Stud Welder Not Ready\nCause:  The Ready Relay for the current stud welding power unit is off. This is caused by the unit having a fault that has not\nbeen reset.\nRemedy:  Reset the fault",
    "041": "SPOT-041 Tool not attached %s\nCause:  A teach pendant instruction was programmed to use a tool change equipment, but that tool was not attached to the arm.\nRemedy:  Make sure that the proper tool is attached to the arm before attempting to use it. Tool changes are done with TPE\nmacros. Make sure that a call to the correct macro is made before attempting the SPOT or BACKUP operation.",
    "042": "SPOT-042 Stud Welder Time Out Fault\nCause:  The robot detected a Stud Welder Time Out Fault from the current controller during a weld. This fault occurs when the\ncontroller does not detect a completed weld or a bad weld after the timer times out. Usually means that the stud is\nwelded to both the target and the gun.\nRemedy:  Once the robot is paused, carefully pry the gun and the stud apart, then reset fault on weld controller and resume the\nprogram.",
    "043": "SPOT-043 Stud Welder Weld Fault\nCause:  The Stud Weld controller has signaled the robot that a weld fault has occurred. This indicates that insufficient current\nwas passed during the weld, generally resulting in a poor quality weld.\nRemedy:  The stud checker will automatically verify the quality of the weld. If bad, check the position of the gun at the weld\nspot. Also check the schedule settings.",
    "044": "SPOT-044 Stud Welder Arc Voltage Fault\nCause:  This fault is signaled by the Stud Weld controller if the voltage sensor reports too little arc voltage during the weld\nprocess. May result in a poor quality weld.\nRemedy:  The stud checker will automatically verify the quality of the weld. If bad, check the position of the gun at the weld\nspot to insure that the tip is the correct distance.",
    "045": "SPOT-045 No Current detected: %s\nCause:  The robot did not see the current sensor input go high throughout the weld, indicating no current.",
    "046": "SPOT-046 Weld auto retried %s time(s)\nCause:  The Auto Retry Weld feature encountered a weld fault and retried the weld the indicated number of times. This\nwarning is posted for every. SPOT instruction encountered in which the weld was retried at least once.\nRemedy:  This is just a warning to let the operator know that a weld was retried, and to alert the operator that weld controller\nmaintenance may be required.",
    "047": "SPOT-047 Collision Detection Alarm\nCause:  A Collision Detection Alarm has been detected. The robot might have collided with an object, or a Tip Stick might\nhave occurred.\nRemedy:  Carefully jog the robot away from the interfering objects, or free the weld gun from the Tip Stick. Verify that the\nCollision Guard option is not set too sensitive. Using the teach pendant:\n1. Press MENU.\n2. Select SETUP.\n3.  Press F1, [TYPE].\n4.  Select COL GUARD.\nVerify that the payload settings are accurate and do not exceed the capacity of the mechanical unit. Check the payload\nsettings by using the teach pendant:\n1. Press MENU.\n2. Press SYSTEM.\n3.  Press F1, [TYPE].\n4. Select Motion.",
    "048": "SPOT-048 No Coll. Guard Reg. Defined\nCause:  No register has been defined for use with the Collision Guard Update macro.\nRemedy:  Use the Collision Guard SETUP screen to define a register for use with the macro.",
    "049": "SPOT-049 Coll. Guard Reg. Data Error\nCause:  The data contained in the Collision Guard macro register is not an integer or is not in the range of 1 to 200.\nRemedy:  Enter the correct data into the Collision Guard macro register.",
    "050": "SPOT-050 Bad Pressure (EP=*) %s\nCause:  An invalid binary equalization pressure was programmed in the teach pendant program.\nRemedy:  In the teach pendant program, check the equalization pressure spot welding instruction EP= value.  Note: The smallest\nvalve pressure allowed is 0. For digital weld controllers, the largest pressure number allowed depends on the width of\nthe Equalization Pressure group output. If this GOUT is 4 I/O points wide, then the maximum pressure is 15. If the\nGOUT is 5 I/O points wide, then the maximum pressure is 31. For serial weld controllers, the maximum pressure is 15.\nRe-program the EP= value in the teach pendant program.",
    "051": "SPOT-051 Undefined Pressure (EP=*) %s\nCause:  The equalization pressure spot welding instruction EP=* was encountered in a teach pendant program, but no previous\npressure value had been assigned. Note: EP=* indicates that the equalization pressure remains unchanged from the last\nvalue.\nRemedy:  Be sure to include a direct equalization pressure value instead of using *.",
    "052": "SPOT-052 Suspect Weld\nCause:  A faulty stud weld has occurred. A pressure value has been used.\nRemedy:  Check the stud that generated the error and remove it if necessary. Select the appropriate recovery type by pressing F4,\n[CHOICE].",
    "053": "SPOT-053 Feeder Low - Gun1\nCause:  The stud feeder for gun 1 is low on studs.\nRemedy:  Add more studs to the feeder for gun 1 at an appropriate time.",
    "054": "SPOT-054 Feeder Low - Gun2\nCause:  The stud feeder for gun 2 is low on studs.\nRemedy:  Add more studs to the feeder for gun 2 at an appropriate time.",
    "055": "SPOT-055 Stud Controller Fault1\nCause:  A weld controller fault has occurred on gun 1.\nRemedy:  Check the stud welding controller for the reason for this fault. Reset the fault, then choose the appropriate type of fault\nrecovery.",
    "056": "SPOT-056 Weld Head Not Retracted-Gun1\nCause:  Studwelding gun 1 has not been retracted.\nRemedy:  Press SHIFT-GUN to return the studwelding gun to its retracted position. Reset the fault, then choose the appropriate\ntype of fault recovery. Verify input configuration and status in the Spot Equip I/O screen. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "057": "SPOT-057 Weld Head Not Retracted-Gun2\nCause:  Studwelding gun2 has not been retracted.\nRemedy:  Press SHIFT-GUN to return the studwelding gun to its retracted position. Reset the fault, then choose the appropriate\ntype of fault recovery. Verify input configuration and status in the Spot Equip I/O screen. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Spot Equip.",
    "058": "SPOT-058 Studwelder - Air Pressure Low\nCause:  The studwelding controller detected that the air pressure has fallen below the minimum operating level of 85 psi.\nRemedy:  Increase the system air pressure.",
    "059": "SPOT-059 Stud Controller Fault2\nCause:  A weld controller fault has occurred on gun 2.\nRemedy:  Check the stud welding controller for the reason for this fault. Reset the fault, then choose the appropriate type of fault\nrecovery.",
    "060": "SPOT-060 Robot Not At Home Position\nCause:  The robot is not at a valid HOME position.\nRemedy:  Jog the robot to a valid HOME position taught in the Reference Position SETUP screen. Verify that the HOME\nposition has been properly taught and enabled.",
    "061": "SPOT-061 Request Failed\nCause:  A request was sent to the timer card, but no response was received.\nRemedy:  Retry the request. The timer card might be busy welding or performing network activities.",
    "062": "SPOT-062 Please retry function again\nCause:  A request was sent to the timer card, but no response was received.\nRemedy:  Retry the request. The timer card might be busy welding or performing network activities.",
    "063": "SPOT-063 %s\nCause:  A weld fault has happened on the weld controller.\nRemedy:  Please refer to manual for weld controller for detailed info on the fault.",
    "064": "SPOT-064 %s\nCause:  A weld alert has happened on the weld controller.\nRemedy:  Please refer to manual for weld controller for detailed info on the alert.",
    "065": "SPOT-065 %s\nCause:  A weld event has happened on the weld controller.\nRemedy:  This is logging information only. No remedy is required.",
    "066": "SPOT-066 Iwc NOT ready\nCause:  Unable to perform operation due to IWC status.\nRemedy:  Refer to the specific IWC error status, and follow that remedy.",
    "067": "SPOT-067 No Shunt Trip output for WC:%s\nCause:  The Shunt Trip output has not been defined.\nRemedy:  Define a DO[] for the Shunt Trip in the Weld Interface I/O screen. Using the teach pendant:\n1. Press I/O.\n2.  Press F1, [TYPE].\n3.  Select Weld Interface.",
    "068": "SPOT-068 Weld done input not mapped %s\nCause:  The weld done input has not been mapped.\nRemedy:  Define weld done IO.",
    "069": "SPOT-069 Studwelder Maintenance on\nCause:  The maintenance input from the studwelder is on.\nRemedy:  Please check the studwelder for the cause of this input.",
    "070": "SPOT-070 Internal Error (system)\nCause:  Internal system error.\nRemedy:  Document the events that led to the error and call your FANUC technical representative.",
    "071": "SPOT-071 Equalization press condition > max gout\nCause:  The number of bits required for the equalization pressure condition is larger than the width of the group output for\nequalization pressure.\nRemedy:  Reduce the equalization pressure condition, or increase the dimension of the group output.",
    "072": "SPOT-072 Equalization pressure IO error\nCause:  The I/O assignment (mapping) for the equalization pressure output is invalid, OR the output is offline.\nRemedy:  Map the I/O properly, or put the I/O back online.",
    "073": "SPOT-073 Dresser speed not acheived.\nCause:  The dresser did not achieve the requested dress speed in time.\nRemedy:  Check the dresser for mechanical issues.",
    "074": "SPOT-074 Tdress sched speed exceeds dresser speed.\nCause:  The speed specified in the dresser schedule exceeds the speed limit of the dresser.\nRemedy:  Reduce the dresser speed in the dresser schedule.",
    "075": "SPOT-075 Max cutter counts exceeded.\nCause:  The number of cuts the dresser has done has exceeded the cutter limit for the dresser.\nRemedy:  Change the cutter blade and reset the cutter count.",
    "076": "SPOT-076 Max tip dresses on Gun #%d exceeded.\nCause:  The number of dresses on the tips has exceeded the dress limit for the tips.\nRemedy:  Change the caps and reset the dress count.",
    "077": "SPOT-077 Tdress min Torque not acheived.\nCause:  The minimum torque required for dress determination was not achieved.\nRemedy:  Verify teach position of gun, and force in TIPDRESS is correct.",
    "078": "SPOT-078 Tdress max Torque exceeded.\nCause:  The maximum torque required for valid dress determination was not exceeded.\nRemedy:  Verify teach position of gun, and force in TIPDRESS is correct.",
    "079": "SPOT-079 Bad Tip Dress Schedule.\nCause:  The Tip Dress schedule specified in the TIPDRESS instruction was greater than the number of available tip dress\nschedules.\nRemedy:  Edit the TIPDRESS instruction and verify the schedule value does not exceed $SGTDCFG.$NUM_SCHED.",
    "080": "SPOT-080 Invalid process axis for dresser.\nCause:  The process axis number for the dresser for the current gun is invalid.\nRemedy:  Verify that $sgtdset[dresser_number].$axis_num is greater than 0 and less than $sgtdcfg.$num_dresrs.",
    "081": "SPOT-081 Max free torque exceeded.\nCause:  The free spinning torque of the dresser has exceeded the user specified maximum.\nRemedy:  Verify operation of the dresser. This alarm could mean that there is an issue with the dressers gearbox.",
    "082": "SPOT-082 Got weld inprocess early %s\nCause:  The Weld In process input was detected before the Weld was initiated.\nRemedy:  Check the weld controller to make sure the weld inprocess input is turning off from the previous weld.",
    "083": "SPOT-083 Early/LATE Blade Contact (PT=%2.1f, BC=%2.1f)\nCause:\n1.  Gun tips may have hit dresser blade earlier than expected.\n2.  Gun or dresser may be out-of-position slightly.\n3.  Tips may be out of alignment.\n4.  Gun zero position may not be correct. (In this case, tip wear may NOT be being performed.)\nRemedy:\n1.  Re-teach the tip dressing position or adjust dresser position.\n2.  Confirm part thickness value and gun zero position are correct.\n3.  Increase early detection position tolerance ($sgtdset[x].$cntct_tol, default=3).",
    "084": "SPOT-084 Invalid dresser number.\nCause:  The dresser number specified does not exist.\nRemedy:  Verify that the dresser number specified is greater than 0 and less than $sgtdcfg.$num_dresrs.",
    "085": "SPOT-085 Speed to low during dress. Check for motor stalling.\nCause:  The dresser motor speed was too low during phase 1 of the dress.\nRemedy:  Verify that the dressing pressure schedule is correct and not too high. If the dressing pressure is too high, it can stall\nthe dressing motor.",
    "086": "SPOT-086 Line Tracking not allowed.\nCause:  Line Tracking is NOT allowed with Spotwelding.\nRemedy:  Use Select->Detail menu to disable tracking (schedule = 0) to disable Tracking for this program.",
    "091": "SPOT-091 91**: XXXX\nCause:  The number of above-mentioned “**” indicate the fault code of weld controller. And, “XXXX” indicate an alarm\nmessage.\nRemedy:  Refer to Nadex DeviceNet weld controller manual for more information about fault code and alarm message.",
    "092": "SPOT-092 ELCB signal detection\nCause:  Change of ELCB auxiliary contact was detected.\nRemedy:  Refer to Nadex DeviceNet weld controller manual for more information about ELCB auxiliary contact.",
    "270": "SPOT-270 Illegal equipment number\nCause:  An illegal equipment number has been specified.\nRemedy:  Inspect the teach pendant program header and enter a valid equipment number.",
    "271": "SPOT-271 Illegal gun index\nCause:  The gun index is invalid.\nRemedy:  Document the events that led to the error, and call your FANUC technical service representative.",
    "272": "SPOT-272 Illegal PX index\nCause:  The PX index is invalid.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "273": "SPOT-273 Illegal pressure profile state\nCause:  The pressure profile state is invalid.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "274": "SPOT-274 Application handshake mismatch(%s)\nCause:  Internal error: application status is inconsistent with task status. Application detected an error, but task did not pause.\nRemedy:  Record number at end of alarm message, and call Fanuc service center.",
    "300": "SPOT-300 Weld sim Enabled\nCause:  This is a warning to inform you that weld simulation has been enabled. This message is posted one time when weld\nsimulate enable has changed from FALSE to TRUE. Note: weld simulate is a test mode function.\nRemedy:  Disable weld simulation, if weld mode simulation is not desired.",
    "301": "SPOT-301 Weld enabled during spot sim\nCause:  This is a warning to inform you that weld enable mode has been activated while weld simulate mode is active. Weld\nsimulate is only available when weld mode is disabled. Therefore, weld simulate will also be disabled.\nRemedy:  Set weld mode to disable, and re-enable weld simulate if you still want to use weld simulate; otherwise no action is\nneeded.",
    "302": "SPOT-302 Weld sim Disabled\nCause:  This warning informs you that weld simulation has been disabled. This message is posted one time, when\n$spotcofig.$sim_enb changes from TRUE to FALSE. Note: Weld simulate is a test mode function.\nRemedy:  Set weld mode to disable, and re-enable weld simulate if you still want to use weld simulate; otherwise, no action is\nneeded.",
    "303": "SPOT-303 %s\nCause:  This message is posted to identify a spot that executed while weld simulation was active. The message will look like:\nSPOT-303: SimWld (Progname,Line#). Note that this message is only posted if $spotcofig.$weld_sim = TRUE, and\n$spotcofig.$sim_warn = TRUE.\nRemedy:  Set $spotcofig.$sim_warn = FALSE, to simulate welds without the SPOT-303 warning. Set $spotcofig.$sim_enb =\nFALSE, to disable weld simulation, and the SPOT-303 warning.",
    "304": "SPOT-304 Stroke disabled during weld retry %s\nCause:  The weld retry function is enabled, and $spotconfig.$stroke_enable changed from TRUE to FALSE during the retry\nprocess. In this case, a weld was started, but not completed. SPOT-304 is posted to provide an opportunity to complete\nthe weld.\nRemedy:  If you want to complete the weld enable stroke, and press FAULT RESET to continue. If you do not want to complete\nthe weld, press FAULT RESET to continue (stroke enable remains false).",
    "305": "SPOT-305 Process custo not found. Disabling.\nCause:  This message indicates that the download of the program failed.\nRemedy:  Document the events that led to the error, and call your FANUC technical service representative.",
    "306": "SPOT-306 Found duplicate model\nCause:  At least two of the models contained the same Model ID.\nRemedy:  1. Review the vision results using either the Runtime screen or Vision Setup screen. 2. Adjust the Vision Process as\nnecessary.",
    "307": "SPOT-307 Gun Tip Test missing model\nCause:  The Gun Tip base or tip model was not found by vision.\nRemedy:  1. Verify that the enclosure LED is operational 2. Verify that the correct caps are on the weld gun 3. Adjust the Vision\nProcess as necessary.",
    "308": "SPOT-308 Robot Tip Test missing model\nCause:  The Robot Tip base or tip model was not found by vision.\nRemedy:  1. Verify that the enclosure LED is operational 2. Verify that the correct caps are on the weld gun 3. Adjust the Vision\nProcess as necessary.",
    "309": "SPOT-309 Tip Alignment missing model\nCause:  One or more of the four models required to make an alignment check was missing.\nRemedy:  1. Verify that the enclosure LED is operational 2. Verify that the correct caps are on the weld gun 3. Adjust the Vision\nProcess as necessary.",
    "310": "SPOT-310 Gun Tip Wear exceeded\nCause:  The Gun tip wear exceeded the user set threshold.\nRemedy:  1. Change Cap and reset nominal condition. 2. Verify user set threshold.",
    "311": "SPOT-311 Gun Cap Changed Length Exceeded\nCause:  The Gun Tip tip model displacement exceeded the user set threshold.\nRemedy:  1. Review the vision results using either the Runtime screen or Vision Setup screen. 2. Verify the user set threshold 3.\nAdjust the Vision Process or equipment as necessary.",
    "312": "SPOT-312 Gun Shank Displaced\nCause:  The Gun Tip base model displacement exceeded the user set threshold.\nRemedy:  1. Review the vision results using either the Runtime screen or Vision Setup screen. 2. Verify the user set threshold. 3.\nAdjust the Vision Process or equipment as necessary.",
    "313": "SPOT-313 Gun Tip Increase Error\nCause:  The Gun cap length increased beyond the user set threshold.\nRemedy:  1. Check cap for material on tip face. 2. Verify the user set threshold. 3. Cap may have been changed without resetting\nnominal conditions. Reset nominal condition.",
    "314": "SPOT-314 Robot Tip Wear exceeded\nCause:  The Robot tip wear exceeded the user set threshold.\nRemedy:  1. Change Cap and reset nominal condition. 2. Verify user set threshold.",
    "315": "SPOT-315 Robot Cap Changed Length Exceeded\nCause:  The Robot Tip tip model displacement exceeded the user set threshold.\nRemedy:  1. Review the vision results using either the Runtime screen or Vision Setup screen. 2. Verify the user set threshold. 3.\nAdjust the Vision Process or equipment as necessary.",
    "316": "SPOT-316 Robot Shank Displaced\nCause:  The Robot Tip base model displacement exceeded the user set threshold.\nRemedy:  1. Review the vision results using either the Runtime screen or Vision Setup screen. 2. Verify the user set threshold. 3.\nAdjust the Vision Process or equipment as necessary.",
    "317": "SPOT-317 Robot Tip Increase Error\nCause:  The Robot cap length increased beyond the user set threshold.\nRemedy:  1. Check cap for material on tip face. 2. Verify the user set threshold. 3. Cap may have been changed without resetting\nnominal conditions. Reset nominal condition.",
    "318": "SPOT-318 Tip Alignment exceeds Threshold\nCause:  The tips were out of alignment.\nRemedy:  1. Adjust equipment to realign weld caps. 2. Adjust the Vision Process as necessary.",
    "319": "SPOT-319 Gun Tip Dress failed\nCause:  Gun tip did not match the tip dressed model.\nRemedy:  1. Re-dress the weld caps. 2. Adjust the Vision Process as necessary.",
    "320": "SPOT-320 Robot Tip Dress failed\nCause:  Robot tip did not match the tip dressed model.\nRemedy:  1. Re-dress the weld caps. 2. Adjust the Vision Process as necessary.",
    "321": "SPOT-321 Gun Cap Change/Type failed\nCause:  Gun Cap did not match the new cap model.\nRemedy:  1. Change Gun Cap. 2. Verify that the correct cap type is on the weld gun. 3. Adjust the Vision Process as necessary.",
    "322": "SPOT-322 Robot Cap Change/Type failed\nCause:  Robot Cap did not match the new cap model.\nRemedy:  1. Change Robot Cap. 2. Verify that the correct cap type is on the weld gun. 3. Adjust the Vision Process as necessary.",
    "323": "SPOT-323 Test message for Recovery\nCause:  This is a message for testing purposes only.\nRemedy:  Please contact your FANUC representative.",
    "324": "SPOT-324 Tip Inspection Continue\nCause:  User chose to Continue from a tip inspection fault.\nRemedy:  NONE. Notification only.",
    "325": "SPOT-325 Tip Inspection Retry\nCause:  User chose to Retry from a tip inspection fault.\nRemedy:  NONE. Notification only.",
    "326": "SPOT-326 Tip Inspection Abort\nCause:  User chose to Abort from a tip inspection fault.\nRemedy:  NONE. Notification only.",
    "327": "SPOT-327 No Recovery Option Selected\nCause:  User did NOT choose any recovery from a tip inspection fault.\nRemedy:  NONE. Notification only.",
    "328": "SPOT-328 Gun Tip Dress shortage\nCause:  Gun Tip Dress Length is shorter than threshold.\nRemedy:  1. Retry Tip Dress 2. Verify that tip dress works correctly. 3.Verify tip dress threshold.",
    "329": "SPOT-329 Robot Tip Dress shortage\nCause:  Robot Tip Dress Length is shorter than threshold.\nRemedy:  1. Retry Tip Dress 2. Verify that tip dress works correctly. 3.Verify tip dress threshold.",
    "330": "SPOT-330 Gun Tip Dress exceeds\nCause:  Gun Tip Dress Length is longer than threshold.\nRemedy:  1. Verify that tip dress time is not too long. 2.Verify tip dress threshold.",
    "331": "SPOT-331 Robot Tip Dress exceeds\nCause:  Robot Tip Dress Length is longer than threshold.\nRemedy:  1. Verify that tip dress time is not too long. 2.Verify tip dress threshold.",
    "332": "SPOT-332 Missing Nominal Length\nCause:  At least one of tip model cannot be found.obot Cap did not match the new cap model.\nRemedy:  1. Verify that the enclosure LED is operational. 2. Verify that the correct caps are on the weld gun. 3. Adjust the\nVision Process as necessary.",
    "333": "SPOT-333 Dress Length Test ignore\nCause:  At least one of tip model cannot be found.obot Cap did not match the new cap model.\nRemedy:  1. Verify that the enclosure LED is operational. 2. Verify that the correct caps are on the weld gun. 3. Adjust the\nVision Process as necessary.",
    "334": "SPOT-334 Stroke limit update not enabled\nCause:  At least one of tip model cannot be found.obot Cap did not match the new cap model.\nRemedy:  1. Verify that the enclosure LED is operational. 2. Verify that the correct caps are on the weld gun. 3. Adjust the\nVision Process as necessary.",
    "350": "SPOT-350 IWC board not found\nCause:  No IWC boards were found on the controller.",
    "351": "SPOT-351 IWC driver not running\nCause:  The IWC driver is waiting for the PC/104 motherboard to complete its reset cycle.\nRemedy:  This is a system programming error. Document the events that led to the error, and call your FANUC technical\nrepresentative.",
    "352": "SPOT-352 Invalid IWC index\nCause:  The specified IWC board is not installed.\nRemedy:  This is a system programming error. Document the events that led to the error, and call your FANUC technical\nrepresentative.",
    "353": "SPOT-353 IWC message in progress\nCause:  A message cannot be sent to the IWC because a previous message transaction is still in progress.\nRemedy:  This is a system programming error. Document the events that led to the error, and call your FANUC technical\nrepresentative.",
    "354": "SPOT-354 Invalid IWC msg buffers\nCause:  The buffers sent for a message transaction are not valid in number and/or length.\nRemedy:  This is a system programming error. Document the events that led to the error, and call your FANUC technical\nrepresentative.",
    "355": "SPOT-355 Invalid IWC function code\nCause:  The function request to the IWC driver is invalid.\nRemedy:  This is a system programming error. Document the events that led to the error, and call your FANUC technical\nrepresentative.",
    "356": "SPOT-356 Checksum error, IWC msg send\nCause:  The IWC reported a checksum error during a message send operation. This might indicate a problem with the board or\ndriver software.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "357": "SPOT-357 Invalid buffer, IWC msg send\nCause:  The IWC reported an invalid buffer during a message send operation. This might indicate a problem with the board or\ndriver software.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "358": "SPOT-358 Checksum error, IWC msg recv\nCause:  An invalid checksum was computed on a message segment received from the IWC board. This might indicate a\nproblem with the board or driver software.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "359": "SPOT-359 Invalid buffer, IWC msg recv\nCause:  An invalid buffer tag was detected on a message segment received from the IWC board. This might indicate a problem\nwith the board or driver software.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "360": "SPOT-360 IWC buffer too small\nCause:  The buffer passed to the IWC driver was too small to hold the message received from the IWC.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "361": "SPOT-361 Ack timeout, IWC msg send\nCause:  The IWC did not acknowledge a message segment that was sent to it.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "362": "SPOT-362 Timeout, IWC msg recv\nCause:  The IWC did not send a response message within the allowable time limit.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "363": "SPOT-363 IWC motherboard error\nCause:  The IWC driver was unable to communicate with the PC/104 motherboard driver.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "364": "SPOT-364 IWC has invalid DPRAM signature\nCause:  An IWC board was detected, but the contents of the dual-port RAM area is not what is expected.\nRemedy:  Make sure that the correct type of IWC board is installed. If the problem persists, swap in a new board.",
    "365": "SPOT-365 Unsupported IWC version/rev level\nCause:  An IWC board was detected, but the version and/or revision level of its dual-port RAM is not supported by the\ninstalled driver.\nRemedy:  Install an IWC with a compatible version level, or check to see if there is an updated version of the driver available.",
    "366": "SPOT-366 Unable to register IWC interrupt\nCause:  The driver was unable to register an interrupt for the IWC board.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "367": "SPOT-367 Only 29 functions allowed in a schedule\nCause:  The user tried to insert more than 29 functions into the schedule. Only 29 functions are allowed in a schedule.\nRemedy:  Do not insert more than 29 functions in a schedule.",
    "368": "SPOT-368 Imp. can only come before weld FCTN\nCause:  The user tried to insert an impulse function(function 60) before a non-weld function.\nRemedy:  Insert the impulse function directly before a weld function.",
    "369": "SPOT-369 FCTN not supported by the timer\nCause:  The user directly entered an invalid function number to be inserted.\nRemedy:  Choose another function from the choice list, or look up the function number of a valid function.",
    "370": "SPOT-370 Could not download schedule %d\nCause:  The schedule failed 2 download tries to the timer.\nRemedy:  Try cycling controller power. If the error still exists, document the events that led to the error, and call your FANUC\ntechnical representative.",
    "371": "SPOT-371 Could not download stepper %d\nCause:  The stepper failed 2 download tries to the timer.\nRemedy:  Try cycling controller power. If the error still exists, document the events that led to the error, and call your FANUC\ntechnical representative.",
    "372": "SPOT-372 Could not read sequence file %d\nCause:  The sequence file could not be read from the FROM.\nRemedy:  Make sure the sequence exists on FROM.",
    "373": "SPOT-373 Could not download setup data\nCause:  The setup data failed 2 download tries to the timer.\nRemedy:  Try cycling controller power. If the error still exists, document the events that led to the error, and call your FANUC\ntechnical representative.",
    "374": "SPOT-374 Could not download Dynamic data\nCause:  The dynamic data failed 2 download tries to the timer.\nRemedy:  Try cycling controller power. If the error still exists, document the events that led to the error, and call your FANUC\ntechnical representative.",
    "375": "SPOT-375 Could not read stepper file %d\nCause:  The stepper file could not be read from the FROM.\nRemedy:  Make sure the stepper exists on FROM.",
    "376": "SPOT-376 Could not read setup file %s\nCause:  The setup file could not be read from the FROM.\nRemedy:  Make sure the setup file exists on FROM.",
    "377": "SPOT-377 Could not read file %s\nCause:  The named file could not be read from the Device.\nRemedy:  Make sure the file exists on the Device.",
    "378": "SPOT-378 IWC ID jumpers incorrect\nCause:  The ID jumpers on the IWC card(s) are not set so that the cards can be identified as card #1 and card #2.\nRemedy:  If there is one card in the system, its ID must be set to 1. If there are two cards, one must be set as card 1 and the other\nas card 2 according to the slots they are in.",
    "379": "SPOT-379 IWC slave busy\nCause:  The IWC slave busy bit is set in the status word.\nRemedy:  Retry the operation after a short delay.",
    "380": "SPOT-380 Invalid IWC Firmware Version\nCause:  The firmware versions on the timer card must be the same if there are 2 timers. Either the firmware version itself is\ndifferent, or the revision level of the firmware is different.\nRemedy:  Make sure that the firmware version and revision level match for both cards. It could be viewed by plugging in one\ncard at a time and viewing the revision level of each one.",
    "381": "SPOT-381 IWC(DG) system error(%d)\nCause:  A communication problem with the timer board has occurred.\nRemedy:  Write down the number of the error and contact a Service Representative:\n1, 2 or 13: The temporary pool area might be almost exhausted.\n3: The timer board could not be initialized successfully.\n4: A parameter could not be written to the timer board successfully.\n5, 6, 7, 8 or 9: A parameter could not be read from the timer board.\n12: A counter value could not be written to the timer board successfully.",
    "382": "SPOT-382 IWC(DG) illegal stepper number(%s)\nCause:  An illegal value for the SN (Stepper Number) field in the reset stepper instruction was used for the Dengensha IWC.\nRemedy:  Change the instruction to use a value that is between 0 and 4.",
    "383": "SPOT-383 IWC(DG) illegal contactor status(%d)\nCause:  Parameter in CONTACTOR instruction is invalid.\nRemedy:  Enter a correct parameter into the CONTACTOR instruction.",
    "384": "SPOT-384 IWC(DG) leak input (%d)\nCause:  The Leak Input signal is on.\nRemedy:\n1.  Remove the cause of the leak.\n2.  Refer to the Weld Interface I/O screen and verify that the Leak Input signal is OFF. Using the teach pendant:\na. Press I/O.\nb.  Press F1, [TYPE].\nc.  Select Spot Equip.\n3.  Perform a reset.",
    "385": "SPOT-385 IWC(DG) illegal counter specified(%s)\nCause:  You have entered an illegal value for the SN= field in the RESET STEPPER instruction while using the IWC\nDengensha Weld Controller.\nRemedy:  The system variable value must be between 0 and 2.",
    "386": "SPOT-386 Reset stepper timeout %s\nCause:  The weld controller did not acknowledge the reset stepper command in the alloted time.\nRemedy:  Check that the weld controller is functioning correctly.",
    "387": "SPOT-387 IWC(DG) timer no response\nCause:  No response was received from the welding timer board. The requested operation could not be executed.\nRemedy:  Turn the power off, then on again.",
    "388": "SPOT-388 IWC(DG) timer acc stat err(%d)\nCause:  Because the access status of the welding timer board remains on, the requested operation cannot be performed.\nRemedy:  Turn the power off, then on again.",
    "389": "SPOT-389 IWC(DG) timer exe flag err(#)\nCause:  Because a welding timer board execution flag remains on, the requested operation cannot be performed.\n1.  The SYSRDY signal is on.\n2.  The data read flag is on.\n3.  The data write flag is on.\n4.  The function name read flag is on.\n5.  The counter set/reset flag is on.\n6.  The welding flag is on.\n7.  The data command execution flag is on.\nRemedy:  Turn the power off, then on again.",
    "390": "SPOT-390 IWC(DG) timer bad response\nCause:  An error occurred in the interface with the welding timer board.\nRemedy:  Contact a service representative. Check whether a software or hardware setting of the welding timer board was\nchanged before the error occurred.",
    "391": "SPOT-391 IWC(DG) timer memory error\nCause:  An error occurred in the hardware system saved in memory in the welding timer board.\nRemedy:  Turn the power off, then on again. The hardware data in timer board is initialized, so readjustment is required.\nFor adjustment data, contact DENGENSHA MFG. CO., LTD..",
    "392": "SPOT-392 IWC(DG) timer not running\nCause:  An error occurred because the welding timer board had not started.\nRemedy:  *systdy from the timer board is not turned off. Contact DENGENSHA MFG. CO., LTD..",
    "393": "SPOT-393 IWC(DG) timer support from Gun1 to Gun4\nCause:  Gun number in RESET STEPPER instruction is invalid.\nRemedy:  Enter a correct gun number into the RESET STEPPER instruction.",
    "394": "SPOT-394 IWC(DG) drv sys error(%d)\nCause:  A system error occurred during processing of communication with the timer board.\nRemedy:  Check the number at the end of the error message.\nSmaller than 500:    Write down the number and contact a service representative.\n500 or greater:  Check the I/O settings such as Shunt trip I/O output and stepper ready I/O output. Check whether\na value outside the range is specified as the I/O type or number.",
    "395": "SPOT-395 IWC(DG) timer now in weld\nCause:  An attempt was made to start welding during welding.\nRemedy:  The weld time-out period is not sufficiently long as compared with the welding time. Set a long value for “Weld\ncomplete time-out” in SETUP/Spot config as compared with the welding time.",
    "396": "SPOT-396 IWC(DG) timer com err %d(%x)\nCause:  The system is unable to communicate with the timer board.\nRemedy:  Check alarms posted with this alarm and do their remedies. And inform it to a service representative.\nWhen the first number is 100 af following,\nSPOT-396 STOP IWC(DG) timer com err 100(Board id)",
    "397": "SPOT-397 Resume not allowed\nCause:  An attempt was made to start welding during welding.\nRemedy:  The weld time-out period is not sufficiently long as compared with the welding time. Set a long value for “Weld\ncomplete time-out” in SETUP/Spot config as compared with the welding time.",
    "398": "SPOT-398 Choose recovery on Alarm recov menu.\nCause:  Choose recovery on Alarm recov menu.\nRemedy:  None.",
    "399": "SPOT-399 IWC FIRMWARE UPGRADED\nCause:  The IWC firmware has been upgraded on the timer card.\nRemedy:  None.",
    "401": "SPOT-401 WTC E01: Controller Failure\nCause:  This is a fault from the WTC weld controller.\nRemedy:  Review the error code remedy information in the WTC weld controller manual.",
    "481": "SPOT-481 WTC IWC(DG) Cant read system_ready(%d)\nCause:  A system error occurred.\nRemedy:  Turn off and back on the power. If the problem persists, check the mounting state of the internal timer board.",
    "482": "SPOT-482 IWC(DG) Failed to set Weld Current flag(%d)\nCause:  A system error occurred.\nRemedy:  Turn the power off and back on. If the problem persists, check the mounting state of the internal timer board. Pull out\nthe timer board and insert it again.",
    "483": "SPOT-483 IWC(DG) Board number duplicated(%d)\nCause:  The board number of the internal timer board is overlapped.\nRemedy:  Check your timer board [SEL] Dip switch T0 T1.\nFor timer board 1, T0=0 T1=0.\nFor timer board 2, T0=1 T1=0.",
    "484": "SPOT-484 IWC(DG) MB Gun no out of range(%d)\nCause:  When the monitor box is used, the series number from the timer board is incorrect.\nRemedy:  Contact a service representative with the value in parentheses, the version number of the robot software, and the\nversion number of the timer software.",
    "485": "SPOT-485 IWC(DG) IWC(DG) DPRAM error (%d)\nCause:  A system error occurred. An error occurred while writing to DPRAM. The timer board may be incorrectly installed.\nRemedy:  Pull out the timer board and insert it again. If the problem persists, a board number is indicated in parentheses after\nSPOT-485. At the same time, detailed information is indicated after SPOT-486. Write down these values and contact a\nservice representative.",
    "486": "SPOT-486 IWC(DG) %x,%x,%x\nCause:  This is a status message for SPOT-485.\nRemedy:  N/A",
    "487": "SPOT-487 IWC(DG) IWC(DG) shunt trip DO error(%d)\nCause:  The shunt trip signal is improperly set. A board number is indicated in parentheses.\nRemedy:  Check if the Shunt trip signal number is correct on the SPOT Weld interface I/O output screen. Turn the power off,\nthen on again after changing.",
    "488": "SPOT-488 IWC(DG) IWC(DG) stepper cmp DO error(%d)\nCause:  The stepper completion output DO is improperly set.",
    "489": "SPOT-489 IWC(DG) IWC(DG) DPRAM out DO error(%d,%d)\nCause:  The DO of the DPRAM output function is improperly set.\nRemedy:  The first number in parentheses is the board number of the board on which an error occurred. The second number is\nthe improper setting number. Change the setting with reference to the I/O alarm indicated together. Turn the power off,\nthen on again after changing.",
    "490": "SPOT-490 IWC(DG) timer now in weld %d\nCause:  An invalid weld controller number was specified.\nRemedy:  The current number of weld controllers that the system is configured for is displayed in the error message. Only use\nthe value one up to and including the number posted on the error line. If you need to increase the number of weld\ncontrollers, then perform a controlled start, and define the new number of weld controllers when prompted during the\nSETUP APPLICATION menu.",
    "491": "SPOT-491 IWC(DG) No Weld detection DO error\nCause:  DO index ($IWCDGDBG[64]) for No Weld detection signal is except 0 and No Weld detection signal was fails to\noutput.\nRemedy:  Check whether DO index ($IWCDGDBG[64]) is assigned correctly. Turn the power off, then on again after changing.",
    "492": "SPOT-492 IWC(DG) PrmWriteErrWC%d S%d %d\nCause:  The system was not able to write the parameter to the timer board. The first number indicates the weld controller\nnumber. The second number indicates the sequence number as follows.\nS0: Common, S1-S255: Schedule, S256: Special function, S257-S260: GUN1-4.\nThe third number indicates the error code number.\nRemedy:  When error code is 2, the value of the parameter is outside the range. Inquire the value of the parameter of the weld\ncontroller maker. Set the system variable to a correct value according to the parameter.\nWC1 S0:$IWCDGCON[1].$PARM[Parameter number]\nWC1 S1-S255:$IWCDGS[Schedule num ber].$PARM[Parameter number]\nWC1 S256:$IWCDGCON[2].$PARM[Parameter number]\nWC1 S257-S260:$IWCDGCON[3-6].$PARM[Parameter number]\nWC2 S0:$IWCDGCON[7].$PARM[Parameter number]\nWC2 S1-S255:$IWCDGS2[Schedule num ber].$PARM[Parameter number]\nWC2 S256:$IWCDGCON[8].$PARM[Parameter number]\nWC2 S257-S260:$IWCDGCON[9-12].$PARM[Parameter number]\nCall your FANUC technical service representative if error code is not 2.",
    "493": "SPOT-493 IWC(DG) NDNW system error(%d)\nCause:  This is internal error.\nRemedy:  Call your FANUC technical service representative.",
    "494": "SPOT-494 NDNW no DSF file(%d)\nCause:  DSF file of the displayed weld controller is not found.\nRemedy:  Acquire DSF file on the initial setting screen.",
    "495": "SPOT-495 NDNW different DSF\nCause:  ID (attribute information) of DSF is not matching to ID of currently connected weld controller.\nRemedy:  Weld controller might have changed places into another mode. Confirm currently connected weld controller. Read\nDSF for currently connected weld controller in initial setting screen if you want to weld with currently connected weld\ncontroller.",
    "496": "SPOT-496 NDNW Device Net Disconnect\nCause:  DeviceNet communication has been disconnected.\nRemedy:  Confirm that:\n1.        Look for the alarm of \"DNET-xxx\" in DeviceNet alarm screen, and refer to the cause and remedy for the alarm.\n2.        Confirm the board used for weld controller is not OFFLINE on board list screen of DeviceNet.\n3.        Confirm the device of node number of weld controller is not OFFLINE on device list screen of DeviceNet.",
    "497": "SPOT-497 NDNW DSF error\nCause:  DSF is not correct.\nRemedy:  Read DSF for currently connected weld controller in initial setting screen.",
    "498": "SPOT-498 NDNW Device Net Disconnect\nCause:  DeviceNet communication has been disconnected.\nRemedy:  Confirm that:\n1.        Look for the alarm of \"DNET-xxx\" in DeviceNet alarm screen, and refer to the cause and remedy for the alarm.\n2.        Confirm the board used for weld controller is not OFFLINE on board list screen of DeviceNet.\n3.        Confirm the device of node number of weld controller is not OFFLINE on device list screen of DeviceNet.",
    "499": "SPOT-499 Timer(%d) is not used\nCause:  Timer number in spot configuration screen is not correct.\nRemedy:  Confirm timer number.",
    "500": "SPOT-500 NDNW request timeout(Board:%d,MAC:%d)\nCause:   There was no response from weld controller.\nRemedy:   Make the DeviceNet communication between weld controller and robot a stable state. Board:%d and MAC:%d\ndisplayed here indicate the weld controller. Confirm the connection and the wiring for the connector.",
    "501": "SPOT-501 Service code error(Board:%d,MAC:%d,Code:0x%x,Ex:%d)\nCause:   Specified service code is not correct.\nRemedy:  There is a possibility that weld controller of unsupport is connected. Call your FANUC technical service representative\nfor more information about this.",
    "502": "SPOT-502 Attr. value is not supported(Board:%d,MAC:%d,C:%d,I:%d,A:%d,V:%d,Ex:%d)\nCause:   Value of the specified attribute is not supported. Data is outside the range.\nRemedy:   There is a possibility that weld controller of unsupport is connected. Call your FANUC technical service representative\nfor more information about this.",
    "503": "SPOT-503 Instance not supported(Board:%d,MAC:%d,C:%d,I:%d,Ex:%d)\nCause:   Specified instance is not supported.\nRemedy:   There is a possibility that weld controller of unsupport is connected. Call your FANUC technical service representative\nfor more information about this.",
    "504": "SPOT-504 Data is longer than size(Board:%d,MAC:%d,Ex:%d)\nCause:   Data is longer than the specified sizes.\nRemedy:   There is a possibility that weld controller of unsupport is connected. Call your FANUC technical service representative\nfor more information about this.",
    "505": "SPOT-505 Data is shorter than size(Board:%d,MAC:%d,Ex:%d)\nCause:   Data has shortened more than the specified sizes.\nRemedy:   There is a possibility that weld controller of unsupport is connected. Call your FANUC technical service representative\nfor more information about this.",
    "506": "SPOT-506 Set request for get only attribute(Board:%d,MAC:%d,C:%d,I:%d,A:%d,Ex:%d)\nCause:   Parameter that cannot be set was set to weld controller.\nRemedy:   There is a possibility that weld controller of unsupport is connected. Call your FANUC technical service representative\nfor more information about this.",
    "507": "SPOT-507 Buffer is not enough(Board:%d,MAC:%d,Ex:%d)\nCause:   Memory to store the response data from weld controller is not in DeviceNet Explicit Message function of robot.\nRemedy:   There is a possibility that $DN_BD_INFO_T[n].$LAG_EM_BUF[m] (n=1-4, m=1-4) is not correctly set. Confirm the\nsettings of DeviceNet. Call your FANUC technical service representative for more information about this when you\ncannot straighten out that problem.",
    "508": "SPOT-508 Attribute is not supported(Board:%d,MAC:%d,C:%d,I:%d,A:%d,Ex:%d)\nCause:   Weld controller doesnt support the attribute that robot specified.",
    "509": "SPOT-509 Error returned(Board:%d,MAC:%d,Err:0x%x,Code:0x%x,C:%d,I:%d,A:%d)\nCause:   Error notification response (0x94) returned from weld controller.\nRemedy:   There is a possibility that weld controller of unsupport is connected. Call your FANUC technical service representative\nfor more information about this.",
    "510": "SPOT-510 NDNW resp.err(Board:%d,MAC:%d,RCode:0x%x,Code:0x%x,C:%d,I:%d,A:%d)\nCause:   The service code from weld controller was an unknown value.\nRemedy:   There is a possibility that $DN_BD_INFO_T[n].$LAG_EM_BUF[m] (n=1-4, m=1-4) is not correctly set. Confirm the\nsettings of DeviceNet. Call your FANUC technical service representative for more information about this when you\ncannot straighten out that problem.",
    "511": "SPOT-511 NDNW DNET internal error(0x%x, Board:%d,MAC:%d)\nCause:   Error occurred when the Explicit Message function was used.\nRemedy:   Call your FANUC technical service representative for more information about this.",
    "512": "SPOT-512 NDNW DSF syntax error(timer:%d,line:%d,type:%d)\nCause:   There is a problem in the DSF file.\nRemedy:   Re-acquire DSF file on the initial setting screen. Call your FANUC technical service representative for more\ninformation about this when you cannot straighten out that problem.",
    "513": "SPOT-513 NDNW Failed to save(I:%d,A:%d)\nCause:   The save of file failed.\nRemedy:   Refer to the cause code.",
    "514": "SPOT-514 NDNW Failed to load(I:%d,A:%d)\nCause:   The load of file failed.\nRemedy:   Refer to the cause code.",
    "515": "SPOT-515 NDNW Failed to reset WC\nCause:   Initialization failed.\nRemedy:   Refer to the cause code.",
    "516": "SPOT-516 NDNW Cannot create a file\nCause:   File was not able to be made to the specified directory.\nRemedy:   Confirm the specified directory.",
    "517": "SPOT-517 NDNW Cannot locate a file\nCause:   File to load doesnt exist in the specified directory.\nRemedy:   Display file screen, and display the directory where the file is preserved. Move to management information screen\nwith the directory opened, and execute load.",
    "519": "SPOT-519 NDNW File has format error\nCause:   Format of file to load is not correct.\nRemedy:   Confirm instance and attribute displayed in SPOT-513, and confirm format of file. Please confirm the format of DSF\nID and date in file when instance and attribute are 0.",
    "520": "SPOT-520 NDNW Value is out of tolerance\nCause:   The value described in file to load is beyond the limits of a set value in DSF.\nRemedy:   Confirm instance and attribute displayed in SPOT-513, and confirm value in file.",
    "521": "SPOT-521 There are 11 or more common classes(timer:%d)\nCause:   Maximum number of common classes in this function(J925) is 10.\nRemedy:   This weld controller cannot be used.",
    "522": "SPOT-522 There are 13 or more series classes(timer:%d)\nCause:   Maximum number of schedule classes in this function(J925) is 12.\nRemedy:   This weld controller cannot be used.",
    "523": "SPOT-523 There are 256 or more instances(timer:%d)\nCause:   Maximum number of instance in this function(J925) is 255.\nRemedy:   This weld controller cannot be used.",
    "524": "SPOT-524 Attribute ID is out of range(timer:%d)\nCause:   Maximum number of attribute ID in this function(J925) is 255.\nRemedy:   This weld controller cannot be used.",
    "525": "SPOT-525 There are 76 or more attribute(timer:%d)\nCause:   Maximum number of class attribute in this function(J925) is 75.\nRemedy:   This weld controller cannot be used.",
    "526": "SPOT-526 NDNW system is not ready(timer:%d)\nCause:   Preparation to display the screen is not complete.\nRemedy:   Read DSF when DSF reading is an incomplete end. Make the DeviceNet communication between weld controller and\nrobot a stable state.",
    "527": "SPOT-527 NDNW DSF ID error(WC-Robot)\nCause:   DSF ID of robot and weld controller is not the same.\nRemedy:   Renew DSF of robot.",
    "529": "SPOT-529 Weld Not ready %s\nCause:   Weld ready signal in weld controller is OFF.\nRemedy:   Refer to Nadex DeviceNet weld controller manual for more information about weld ready signal."
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = data;
  if (global.FanucAlarms) global.FanucAlarms._put("SPOT", data);
})(typeof window !== 'undefined' ? window : globalThis);
